package theme

import (
	"embed"
	"encoding/xml"
	"fmt"
	"image/color"
	"strings"
	"sync"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/theme"
)

// The duotone icon set.
//
// Each icon in icons/ has two layers: "fg", the outline and detail drawn at
// full strength, and "duo", a soft fill drawn underneath at DuoOpacity. The
// SVGs are generated by generate/icons from a small geometry library, so every
// outline has the same weight and every hole is wound correctly.
//
// Fyne cannot render this directly. Its recolouring (internal/svg.Colorize)
// rewrites the colour *and* fill-opacity of every path, which would flatten
// the soft layer into a solid blob. So an Icon gives two views of itself:
//
//   - For(colour) renders both layers with explicit colours into a plain
//     StaticResource, which Fyne leaves alone. Custom widgets use this and
//     choose the colour themselves (hover, importance, disabled).
//   - The Icon itself is a fyne.ThemedResource exposing only the fg layer, so
//     stock widgets (widget.Button, widget.Icon, Entry action items) still
//     recolour it with the theme exactly as before.

//go:embed icons/*.svg
var iconFS embed.FS

// DuoOpacity is the strength of the soft layer relative to the outline.
const DuoOpacity = 0.32

// Icon is one duotone glyph.
type Icon struct {
	name    string
	viewBox string
	fg      []string // path data, full strength
	duo     []string // path data, soft fill

	once   sync.Once
	themed []byte
}

var _ fyne.ThemedResource = (*Icon)(nil)

// iconRegistry lists every icon by name, for the icon sheet and the tests.
var iconRegistry = map[string]*Icon{}

// loadIcon returns the icon named name from icons/<name>.svg. A missing or
// broken file is a build mistake, so it panics at start-up rather than
// rendering an empty square somewhere deep in the UI.
func loadIcon(name string) *Icon {
	ic := &Icon{name: name, viewBox: "0 0 24 24"}
	data, err := iconFS.ReadFile("icons/" + name + ".svg")
	if err != nil {
		panic("icon " + name + ": no icons/" + name + ".svg")
	}
	if err := ic.parse(data); err != nil {
		panic(fmt.Sprintf("icon %s: %v", name, err))
	}
	iconRegistry[name] = ic
	return ic
}

type iconDoc struct {
	ViewBox string `xml:"viewBox,attr"`
	Paths   []struct {
		Layer string `xml:"data-layer,attr"`
		D     string `xml:"d,attr"`
	} `xml:"path"`
}

func (ic *Icon) parse(data []byte) error {
	var doc iconDoc
	if err := xml.Unmarshal(data, &doc); err != nil {
		return err
	}
	if doc.ViewBox != "" {
		ic.viewBox = doc.ViewBox
	}
	for _, p := range doc.Paths {
		switch p.Layer {
		case "duo":
			ic.duo = append(ic.duo, p.D)
		default:
			ic.fg = append(ic.fg, p.D)
		}
	}
	if len(ic.fg) == 0 {
		return fmt.Errorf("no fg layer")
	}
	return nil
}

// IconName returns the icon's registry name.
func (ic *Icon) IconName() string { return ic.name }

// Name implements fyne.Resource. Fyne caches rasterised SVGs by name, so the
// themed view and every coloured view must have distinct names.
func (ic *Icon) Name() string { return "wg-" + ic.name + ".svg" }

// Content implements fyne.Resource: the fg layer alone, in white, ready for
// Fyne to recolour.
func (ic *Icon) Content() []byte {
	ic.once.Do(func() { ic.themed = ic.markup("#ffffff", "") })
	return ic.themed
}

// ThemeColorName implements fyne.ThemedResource.
func (ic *Icon) ThemeColorName() fyne.ThemeColorName { return theme.ColorNameForeground }

// markup renders the SVG. An empty duoHex omits the soft layer.
func (ic *Icon) markup(fgHex, duoHex string) []byte {
	var b strings.Builder
	fmt.Fprintf(&b, `<svg xmlns="http://www.w3.org/2000/svg" viewBox="%s">`, ic.viewBox)
	if duoHex != "" {
		for _, d := range ic.duo {
			fmt.Fprintf(&b, `<path fill="%s" fill-opacity="%g" d="%s"/>`, duoHex, DuoOpacity, d)
		}
	}
	for _, d := range ic.fg {
		fmt.Fprintf(&b, `<path fill="%s" d="%s"/>`, fgHex, d)
	}
	b.WriteString(`</svg>`)
	return []byte(b.String())
}

var (
	iconCacheMu sync.Mutex
	iconCache   = map[string]fyne.Resource{}
)

// For returns the icon rendered in c, with the soft layer in the same hue.
func (ic *Icon) For(c color.Color) fyne.Resource {
	return ic.ForDuo(c, c)
}

// ForDuo renders the outline in fg and the soft layer in duo. Most callers
// want For; this is for status icons whose fill carries its own meaning.
func (ic *Icon) ForDuo(fg, duo color.Color) fyne.Resource {
	fgHex, duoHex := hexOf(fg), hexOf(duo)
	key := ic.name + fgHex + duoHex

	iconCacheMu.Lock()
	defer iconCacheMu.Unlock()
	if r, ok := iconCache[key]; ok {
		return r
	}
	name := fmt.Sprintf("wg-%s-%s-%s.svg", ic.name, fgHex[1:], duoHex[1:])
	r := fyne.NewStaticResource(name, ic.markup(fgHex, duoHex))
	iconCache[key] = r
	return r
}

// hexOf formats a colour as #rrggbb. Alpha is dropped: icon translucency
// belongs to the layer opacity, not to the colour.
func hexOf(c color.Color) string {
	n := color.NRGBAModel.Convert(c).(color.NRGBA)
	return fmt.Sprintf("#%02x%02x%02x", n.R, n.G, n.B)
}

// Icons returns every registered icon, for the icon sheet and the gallery.
func Icons() map[string]*Icon { return iconRegistry }
